  [424645] = { "呪文のメモを翻訳し、新しいルーン彫りのレシピにします。筆者の略記法の参考資料が必要です。", nil, 0xadb28b80, nil, "um" },
  [424715] = { "Starsurgeのアビリティを得ます：\n\n$I1\nほとばしる星のエネルギーを放ち、$N1のArcaneダメージを与え、$D1の間、次の$N2回のStarfireの詠唱のダメージを$N3%増加させます。\n\nStarsurgeは、WrathまたはStarfireから発動する、またはその恩恵を受ける大半の才能と効果の恩恵を受け、それらを発動させます。", nil, 0xb4f41bbf, nil, "um" },
  [424718] = { "脚部にStarsurgeのルーンを刻みます：\n\n$I1\n星のエネルギーを放ち、$N1のArcaneダメージを与え、$D1の間、次の$N2回のStarfireのダメージを$N3%増加させます。\n\nStarsurgeは、WrathまたはStarfireによって発動する、またはそれらを強化するほとんどのタレントと効果の恩恵を受け、それらを発動させます。", nil, 0x9a8618a9, nil, "um" },
  [424759] = { { "Berserkのアビリティを得ます：\n\n$I1\n|CFFFFFFFF必要：Cat Form、Bear Form、Dire Bear Form|R\nPrimal Biteのアビリティが最大$N1体の対象に命中するようになり、クールダウンがなくなり、Combo Pointを生み出すアビリティのクリティカル率が$N2%上昇します。効果時間中、Fear効果を解除し、Fear効果を無効化します。$D1持続します。", "Berserkのアビリティを得ます：\n\n$I1\n|CFFFF2020必要：Cat Form、Bear Form、Dire Bear Form|R\nPrimal Biteのアビリティが最大$N1体の対象に命中するようになり、クールダウンがなくなり、Combo Pointを生み出すアビリティのクリティカル率が$N2%上昇します。効果時間中、Fear効果を解除し、Fear効果を無効化します。$D1持続します。", shape = { "3/1", "3/1" } }, nil, 0x1cd4f479, nil, "um" },
  [424760] = { { "ベルトにBerserkのルーンを刻みます：\n\n$I1\n|CFFFFFFFF必要：Cat Form、Bear Form、Dire Bear Form|R\nPrimal Biteが最大$N1体の対象に命中するようになり、クールダウンがなくなり、Combo Pointを生成するアビリティのクリティカル率が$N2%上昇します。効果中はFear効果が解除され、Fear効果に対する免疫を得ます。$D1持続します。", "ベルトにBerserkのルーンを刻みます：\n\n$I1\n|CFFFF2020必要：Cat Form、Bear Form、Dire Bear Form|R\nPrimal Biteが最大$N1体の対象に命中するようになり、クールダウンがなくなり、Combo Pointを生成するアビリティのクリティカル率が$N2%上昇します。効果中はFear効果が解除され、Fear効果に対する免疫を得ます。$D1持続します。", shape = { "3/1", "3/1" } }, nil, 0xcfb3cf54, nil, "um" },
  [424762] = { "King of the Jungleのアビリティを得ます：\n\n$I1\nTiger's Furyが即座にエネルギーを$N1与えるようになります。", nil, 0xfb8ee464, nil, "um" },
  [424765] = { "ブーツにKing of the Jungleのルーンを刻みます：\n\n$I1\nTiger's Furyで即座にエネルギーを$N1得るようになります。", nil, 0xd414c04d, nil, "um" },
  [424785] = { "敵を容赦なく切りつけて武器ダメージの$N1%を与え、対象を出血させて$D2の間、$N3秒ごとに$N2のダメージを与えます。最大$N5回までスタックします。スタックごとに、Saber SlashとSinister Strikeのダメージも$N6%増加します。コンボポイントを$N7獲得します。\n\nSaber SlashはSinister Strikeから発動する、またはSinister Strikeを強化するすべてのタレントと効果の恩恵を受けます。", "出血により、$N2秒ごとに$N1のダメージを受けています。\nSaber SlashとSinister Strikeから受けるダメージが$N3%増加しています。", 0x72e45558, 0x7fbbf470, "uu" },
  [424788] = { "シュレッダーの残骸から予備部品を回収します。", nil, 0x30b9e1d2, nil, "um" },
  [424799] = { "即座にオフハンド武器で攻撃して通常のオフハンド武器ダメージを与え、$N1%の確率でオフハンド武器の毒を対象に付与します。遅い武器ほど多くのエネルギーを必要とします。コンボポイントを$N2得ます。\n\nShivはSinister Strikeで発動する、またはSinister Strikeを変化させるすべてのタレントと効果の恩恵を受けます。", nil, 0xb5aa7d3f, nil, "um" },
  [424800] = { "オフハンド武器で即座に攻撃し、100%の確率でオフハンド武器の毒を対象に付与します。遅い武器ほど多くのエネルギーを必要とします。コンボポイントを$N2獲得します。", nil, 0x282f1a89, nil, "um" },
  [424919] = { "即座にオフハンド武器で攻撃して通常のオフハンド武器ダメージを与え、$D1の間、またはパリィに成功するまで、パリィ率を$N1%上昇させます。Main Gaucheの使用後$D2の間、Sinister Strikeのエネルギーコストが$N4減少し、発生させる脅威が$N5%増加し、Rolling with the Punchesのスタックを得られるようになり、Sinister StrikeとEviscerateの与えるダメージが$N6%増加します。コンボポイントを$N7得ます。\n\nMain GaucheはSinister Strikeで発動する、またはSinister Strikeを変化させるほとんどのタレントと効果の恩恵を受けます。Main Gaucheの効果はMain Gauche自体のコストを軽減したり強化したりしません。", "Parry率が$N1%上昇しています。", 0xc4245e6a, 0xea59a9be, "uu" },
  [424925] = { { "BackstabとAmbushのアビリティのエネルギーコストを$N1減少させ、プレイヤー以外が操作する対象に与えるダメージを$N2%増加させます。Mutilateには適用されません。", "BackstabとAmbushのアビリティのエネルギーコストを$N1減少させ、プレイヤー以外が操作する対象に与えるダメージを$N2%増加させます。他のルーンから習得したアビリティには適用されません。", shape = { "2/0", "2/0" } }, nil, 0x2c1b4225, nil, "um" },
  [424979] = { "Saber Slashのアビリティを得ます：\n\n$I1\n敵を激しく切り裂いて武器ダメージの$N1%を与え、対象を出血させて$D2の間、$D1ごとに$N2のダメージを与えます。最大$N5回までスタックします。スタックごとに、Saber SlashとSinister Strikeの与えるダメージも$N6%増加します。コンボポイントを$N7獲得します。\n\nSaber Slashは、Sinister Strikeから発動する、またはSinister Strikeを強化するすべての才能と効果の恩恵を受けます。", nil, 0xd3ed0eab, nil, "um" },
  [424980] = { "Cutthroatのアビリティを得ます：\n\n$I1\nBackstabに、$N1%の確率で$D1以内の次のAmbushにStealthを不要にする効果を与えます。", nil, 0xc5e9cf59, nil, "um" },
  [424982] = { "Main Gaucheのアビリティを得ます：\n\n$I1\nオフハンド武器で即座に攻撃して通常のオフハンド武器ダメージを与え、$D1の間、または受け流しに成功するまで、受け流しの確率を$N1%上昇させます。Main Gaucheの使用後$D2の間、Sinister Strikeのエネルギーコストが$N4減少し、発生する脅威が$N5%増加し、Rolling with the Punchesのスタックを付与するようになり、Sinister StrikeとEviscerateの両方の与えるダメージが$N6%増加します。コンボポイントを$N7獲得します。\n\nMain Gaucheは、Sinister Strikeから発動する、またはSinister Strikeを強化する大半の才能と効果の恩恵を受けます。Main Gaucheの効果はMain Gauche自体のコストを下げたり強化したりはしません。", nil, 0xb2b7138c, nil, "um" },
  [424983] = { { "Slaughter from the Shadowsのアビリティを得ます：\n\n$I1\nBackstabとAmbushのアビリティのエネルギーコストを$N1減少させ、プレイヤー以外が操作する対象に与えるダメージを$N2%増加させます。Mutilateには適用されません。", "Slaughter from the Shadowsのアビリティを得ます：\n\n$I1\nBackstabとAmbushのアビリティのエネルギーコストを$N1減少させ、プレイヤー以外が操作する対象に与えるダメージを$N2%増加させます。他のルーンから習得したアビリティには適用されません。", shape = { "2/0", "2/0" } }, nil, 0x9b32cf65, nil, "um" },
  [424984] = { "手袋にSaber Slashのルーンを刻みます：\n\n$I1\n敵を激しく斬りつけて武器ダメージの$N1%を与え、対象を出血させて$D2の間$D1ごとに$N2のダメージを与えます。最大$N5回までスタックします。スタックごとに、Saber SlashとSinister Strikeのダメージも$N6%増加します。コンボポイントを$N7獲得します。\n\nSaber Slashは、Sinister Strikeから発動する、またはSinister Strikeを変化させるすべてのタレントと効果の恩恵を受けます。", nil, 0x9ee44fa7, nil, "um" },
  [424988] = { "手袋にCutthroatのルーンを刻みます：\n\n$I1\nBackstabは$N1%の確率で、$D1以内の次のAmbushをStealthなしで使用可能にします。", nil, 0xe753d816, nil, "um" },
  [424990] = { "手袋にMain Gaucheのルーンを刻みます：\n\n$I1\nオフハンド武器で即座に攻撃して通常のオフハンド武器ダメージを与え、$D1の間、または受け流しに成功するまで、受け流しの確率を$N1%上昇させます。Main Gauche使用後$D2の間、Sinister Strikeのエネルギーコストが$N4減少し、生み出す脅威が$N5%増加し、Rolling with the Punchesのスタックを付与し、Sinister StrikeとEviscerateの両方のダメージが$N6%増加します。コンボポイントを$N7獲得します。\n\nMain Gaucheは、Sinister Strikeから発動する、またはSinister Strikeを変化させるほとんどのタレントと効果の恩恵を受けます。Main Gaucheの効果はMain Gauche自身のコストを軽減せず、強化もしません。", nil, 0x279ea807, nil, "um" },
  [424992] = { { "胸部か法衣にSlaughter from the Shadowsのルーンを刻みます：\n\n$I1\nBackstabとAmbushのエネルギーコストを$N1減少させ、プレイヤー以外が操作する対象に与えるダメージを$N2%増加させます。Mutilateには適用されません。", "胸部か法衣にSlaughter from the Shadowsのルーンを刻みます：\n\n$I1\nBackstabとAmbushのエネルギーコストを$N1減少させ、プレイヤー以外が操作する対象に与えるダメージを$N2%増加させます。他のルーンで習得したアビリティには適用されません。", shape = { "2/0", "2/0" } }, nil, 0x9ddaea85, nil, "um" },
